import itertools

def generate_polyominoes(area):
    polyominoes = [frozenset([(0,0)])]
    for _ in range(area - 1):
        new_polyominoes = set()
        for poly in polyominoes:
            neighbors = set()
            for x, y in poly:
                for dx, dy in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nx, ny = x+dx, y+dy
                    if (nx, ny) not in poly:
                        neighbors.add((nx, ny))
            for neighbor in neighbors:
                new_poly = set(poly)
                new_poly.add(neighbor)
                min_x = min(x for x, y in new_poly)
                min_y = min(y for x, y in new_poly)
                normalized = frozenset((x - min_x, y - min_y) for x, y in new_poly)
                new_polyominoes.add(normalized)
        polyominoes = list(new_polyominoes)
    return polyominoes

def has_k_colors(poly, a, b, k):
    colors = set()
    for x, y in poly:
        colors.add((a*x + b*y) % k)
    return len(colors) == k

def solve_for_k(k, area):
    poly_list = generate_polyominoes(area)
    for a in range(k):
        for b in range(k):
            all_have_k = True
            for poly in poly_list:
                if not has_k_colors(poly, a, b, k):
                    all_have_k = False
                    break
            if all_have_k:
                return True, (a, b)
    return False, None

for k in range(2, 6):
    print(f"k={k}:")
    for area in range(k, k+5):
        res, _ = solve_for_k(k, area)
        print(f"  area={area}: {res}")

