def get_max_2_coloured_area_v2(k):
    # Let's try different linear colourings: (ax + by) % k
    # and find the one that minimizes the max area of a (k-1)-coloured polyomino.

    grid_size = 12
    min_max_area = float('inf')

    for a in range(1, k):
        for b in range(1, k):
            if (a, b) == (1, 1): # Already tried something similar
                pass

            grid = [[(a*x + b*y) % k for x in range(grid_size)] for y in range(grid_size)]

            max_area = 0
            for color_to_remove in range(k):
                visited = [[False for _ in range(grid_size)] for _ in range(grid_size)]
                for y in range(grid_size):
                    for x in range(grid_size):
                        if grid[y][x] != color_to_remove and not visited[y][x]:
                            area = 0
                            stack = [(x, y)]
                            visited[y][x] = True
                            while stack:
                                cx, cy = stack.pop()
                                area += 1
                                for dx, dy in [(0,1), (0,-1), (1,0), (-1,0)]:
                                    nx, ny = cx + dx, cy + dy
                                    if 0 <= nx < grid_size and 0 <= ny < grid_size and \
                                       grid[ny][nx] != color_to_remove and not visited[ny][nx]:
                                        visited[ny][nx] = True
                                        stack.append((nx, ny))
                            max_area = max(max_area, area)

            if max_area < min_max_area:
                min_max_area = max_area

    return min_max_area

print(f"k=3: {get_max_2_coloured_area_v2(3)}")

